import 'dart:convert';
import 'dart:ui' as ui;

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart' show rootBundle;

import 'orchard_girl_rig.dart';

/// Parsed `assets/game/characters/rig/manifest.json`.
///
/// The manifest is generated by `tools/character_rig/extract_layers.py`, so the
/// game never hard-codes layer rectangles or joint pivots.
@immutable
class OrchardGirlRigData {
  const OrchardGirlRigData({
    required this.canvasWidth,
    required this.canvasHeight,
    required this.joints,
    required this.layers,
    required this.order,
    required this.moodFaces,
    required this.variants,
  });

  final double canvasWidth;
  final double canvasHeight;
  final Map<String, ui.Offset> joints;
  final Map<String, OrchardGirlLayerRect> layers;
  final List<String> order;
  final Map<String, OrchardGirlFace> moodFaces;
  final Map<String, Map<String, String>> variants;

  static const String manifestAsset =
      'assets/game/characters/rig/manifest.json';

  factory OrchardGirlRigData.fromJson(Map<String, dynamic> json) {
    final canvas = (json['canvas'] as List<dynamic>).cast<num>();
    final joints = <String, ui.Offset>{};
    for (final entry in (json['joints'] as Map<String, dynamic>).entries) {
      final point = (entry.value as List<dynamic>).cast<num>();
      joints[entry.key] = ui.Offset(
        point[0].toDouble(),
        point[1].toDouble(),
      );
    }
    final layers = <String, OrchardGirlLayerRect>{};
    for (final entry in (json['layers'] as Map<String, dynamic>).entries) {
      final rect =
          ((entry.value as Map<String, dynamic>)['rect'] as List<dynamic>)
              .cast<num>();
      layers[entry.key] = OrchardGirlLayerRect(
        rect[0].toDouble(),
        rect[1].toDouble(),
        rect[2].toDouble(),
        rect[3].toDouble(),
      );
    }
    final moodFaces = <String, OrchardGirlFace>{};
    for (final entry in (json['moodFace'] as Map<String, dynamic>).entries) {
      moodFaces[entry.key] =
          OrchardGirlFaceJson.fromJson(entry.value as Map<String, dynamic>);
    }
    final variants = <String, Map<String, String>>{};
    for (final entry in (json['variants'] as Map<String, dynamic>).entries) {
      variants[entry.key] =
          (entry.value as Map<String, dynamic>).cast<String, String>();
    }
    return OrchardGirlRigData(
      canvasWidth: canvas[0].toDouble(),
      canvasHeight: canvas[1].toDouble(),
      joints: joints,
      layers: layers,
      order: (json['order'] as List<dynamic>).cast<String>(),
      moodFaces: moodFaces,
      variants: variants,
    );
  }

  static Future<OrchardGirlRigData> load() async {
    final raw = await rootBundle.loadString(manifestAsset);
    return OrchardGirlRigData.fromJson(
      jsonDecode(raw) as Map<String, dynamic>,
    );
  }

  OrchardGirlFace faceFor(String mood) =>
      moodFaces[mood] ?? moodFaces['idle'] ?? const OrchardGirlFace(
        eyes: 'open',
        brows: 'neutral',
        mouth: 'smile',
      );

  /// Asset key for a face part, e.g. `eyes_open_left`.
  String faceAsset(String group, String variant, String side) =>
      '${group}_${variant}_$side';
}

@immutable
class OrchardGirlLayerRect {
  const OrchardGirlLayerRect(this.x, this.y, this.width, this.height);

  final double x;
  final double y;
  final double width;
  final double height;
}

extension OrchardGirlFaceJson on OrchardGirlFace {
  static OrchardGirlFace fromJson(Map<String, dynamic> json) => OrchardGirlFace(
        eyes: json['eyes'] as String,
        brows: json['brows'] as String,
        mouth: json['mouth'] as String,
      );
}

/// Decoded layer images, loaded once and shared by every character instance.
///
/// Images are decoded off the raster thread and cached for the lifetime of the
/// app; [release] drops them when the last widget goes away so a long session
/// cannot hold two copies of the art.
class OrchardGirlImages {
  OrchardGirlImages._(this.data, this.images);

  final OrchardGirlRigData data;
  final Map<String, ui.Image> images;

  static OrchardGirlImages? _cached;
  static Future<OrchardGirlImages>? _loading;
  static int _references = 0;

  /// Increments the reference count and returns the shared images.
  static Future<OrchardGirlImages> acquire() {
    _references++;
    final cached = _cached;
    if (cached != null) return Future<OrchardGirlImages>.value(cached);
    return _loading ??= _load();
  }

  /// Decrements the reference count and disposes the images at zero.
  static void release() {
    if (_references > 0) _references--;
    if (_references > 0) return;
    final cached = _cached;
    _cached = null;
    _loading = null;
    if (cached == null) return;
    for (final image in cached.images.values) {
      image.dispose();
    }
  }

  /// Loads the manifest and every layer for the app's asset bundle.
  static Future<OrchardGirlImages> _load() async {
    final data = await OrchardGirlRigData.load();
    final images = <String, ui.Image>{};
    try {
      await Future.wait(data.layers.keys.map((name) async {
        final bytes =
            await rootBundle.load('assets/game/characters/rig/$name.png');
        final codec =
            await ui.instantiateImageCodec(bytes.buffer.asUint8List());
        final frame = await codec.getNextFrame();
        images[name] = frame.image;
        codec.dispose();
      }));
    } catch (error) {
      for (final image in images.values) {
        image.dispose();
      }
      _loading = null;
      rethrow;
    }
    final result = OrchardGirlImages._(data, images);
    _cached = result;
    return result;
  }

  ui.Image? layer(String key) => images[key];

  @visibleForTesting
  static int get referenceCount => _references;

  @visibleForTesting
  static bool get isLoaded => _cached != null;
}
